<?php
declare(strict_types=1);
require_once __DIR__.'/domain.php';
function sc_config(): array { $file=__DIR__.'/config.php';if(!is_file($file))sc_fail(503,'Kurulum gerekli: private/config.example.php dosyasını config.php olarak kopyalayıp veritabanı ayarlarını doldurun.');$c=require $file;if(!is_array($c)||empty($c['db_name'])||empty($c['db_user']))sc_fail(503,'Veritabanı ayarları eksik.');return $c; }
function sc_db(array $c): PDO { try{return new PDO('mysql:host='.($c['db_host']??'localhost').';port='.(int)($c['db_port']??3306).';dbname='.$c['db_name'].';charset=utf8mb4',$c['db_user'],$c['db_password']??'',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);}catch(PDOException){sc_fail(503,'Veritabanına bağlanılamadı. config.php içindeki veritabanı adı, kullanıcı, parola ve sunucuyu kontrol edin.');} }
function sc_query(PDO $db,string $sql,array $args=[]): PDOStatement { $q=$db->prepare($sql);$q->execute($args);return $q; }
function sc_ms(): int { return (int)floor(microtime(true)*1000); }
function sc_ready(PDO $db): void { try{if(!sc_query($db,'SELECT id FROM sc_admin WHERE id=1')->fetch())sc_fail(503,'İlk kurulum tamamlanmadı. /setup.php adresini açın.');}catch(PDOException){sc_fail(503,'İlk kurulum gerekli. /setup.php adresini açın.');} }
function sc_business(PDO $db): array { return json_decode(sc_query($db,'SELECT json FROM sc_business WHERE id=1')->fetchColumn(),true,512,JSON_THROW_ON_ERROR); }
function sc_save_business(PDO $db,array $business): void { $json=json_encode($business,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);if(strlen($json)>8*1024*1024)sc_fail(400,'Çalışan fotoğraflarının toplam boyutu çok yüksek. Daha küçük fotoğraflar kullanın.');sc_query($db,'UPDATE sc_business SET json=? WHERE id=1',[$json]); }
function sc_tx(PDO $db,callable $fn): mixed { $db->beginTransaction();try{sc_query($db,'SELECT id FROM sc_business WHERE id=1 FOR UPDATE')->fetch();$result=$fn();$db->commit();return $result;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;} }
function sc_audit(PDO $db,string $action,?string $id=null): void { sc_query($db,'INSERT INTO sc_audit(action,entity_id,created_at) VALUES(?,?,?)',[$action,$id,sc_now()]); }
function sc_booking(array|false $row): ?array { if(!$row)return null;return ['id'=>$row['id'],'code'=>$row['code'],'barberId'=>(int)$row['barber_id'],'date'=>$row['date'],'time'=>sc_clock((int)$row['start']),'duration'=>(int)$row['duration'],'name'=>$row['name'],'phone'=>$row['phone'],'paymentMethod'=>$row['payment_method'],'status'=>$row['status'],'paymentStatus'=>'unpaid','createdAt'=>$row['created_at'],'services'=>json_decode($row['services_json'],true,512,JSON_THROW_ON_ERROR),'total'=>$row['total']===null?null:(int)$row['total'],'priceFrom'=>(bool)$row['price_from']]; }
function sc_bookings(PDO $db,string $date): array { return array_map('sc_booking',sc_query($db,'SELECT * FROM sc_appointments WHERE date=? ORDER BY start,barber_id',[$date])->fetchAll()); }
function sc_find_barber(array $business,int $id): ?array { foreach($business['barbers'] as $b)if($b['id']===$id)return $b;return null; }
function sc_throttle(PDO $db,string $kind,int $max,int $seconds=900): void { $now=sc_ms();$until=$now+$seconds*1000;$ip=$_SERVER['REMOTE_ADDR']??'unknown';$key=hash('sha256',$kind.':'.$ip);sc_query($db,'DELETE FROM sc_rate_limits WHERE expires<?',[$now]);sc_query($db,'INSERT INTO sc_rate_limits(id,attempts,expires) VALUES(?,1,?) ON DUPLICATE KEY UPDATE attempts=IF(expires<?,1,attempts+1), expires=IF(expires<?,?,expires)',[$key,$until,$now,$now,$until]);$row=sc_query($db,'SELECT attempts FROM sc_rate_limits WHERE id=?',[$key])->fetch();if((int)$row['attempts']>$max)sc_fail(429,'Çok fazla deneme. Biraz bekleyip tekrar deneyin.'); }
function sc_session(PDO $db): ?array { $token=$_COOKIE['session']??'';if(!is_string($token)||!preg_match('/^[a-f0-9]{64}$/D',$token))return null;$row=sc_query($db,'SELECT * FROM sc_sessions WHERE token_hash=? AND expires>?',[hash('sha256',$token),sc_ms()])->fetch();return $row?:null; }
function sc_cookie(string $token,array $c,bool $clear=false): void { setcookie('session',$token,['expires'=>$clear?time()-3600:time()+8*3600,'path'=>'/','secure'=>(bool)($c['cookie_secure']??true),'httponly'=>true,'samesite'=>'Strict']); }
function sc_password_hash(string $password): string { return password_hash(hash('sha256',$password),PASSWORD_DEFAULT,['cost'=>12]); }
function sc_password_verify(string $password,string $hash): bool { return password_verify(hash('sha256',$password),$hash); }
function sc_origin(array $c): void { if(empty($_SERVER['HTTP_ORIGIN']))return;$origin=$_SERVER['HTTP_ORIGIN'];$allowed=array_values(array_filter(array_merge([$c['public_origin']??''],$c['allowed_origins']??[])));if(!$allowed)$allowed=[(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off'?'https://':'http://').($_SERVER['HTTP_HOST']??'')];if(!in_array($origin,$allowed,true))sc_fail(403,'İstek kaynağı geçersiz.'); }
function sc_body(): array { if(!str_starts_with(strtolower($_SERVER['CONTENT_TYPE']??''),'application/json'))sc_fail(415,'JSON isteği gerekli.');if((int)($_SERVER['CONTENT_LENGTH']??0)>1048576)sc_fail(413,'İstek çok büyük.');$raw=file_get_contents('php://input',false,null,0,1048577);if(strlen($raw)>1048576)sc_fail(413,'İstek çok büyük.');try{$object=json_decode($raw?:'{}',false,512,JSON_THROW_ON_ERROR);if(!$object instanceof stdClass)sc_fail(400,'Geçersiz veri.');return json_decode($raw?:'{}',true,512,JSON_THROW_ON_ERROR);}catch(JsonException){sc_fail(400,'Geçersiz JSON.');} }
function sc_headers(): void { header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');header('X-Content-Type-Options: nosniff');header('X-Frame-Options: DENY');header('Referrer-Policy: same-origin'); }
function sc_json(int $status,mixed $value): never { http_response_code($status);echo json_encode($value,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE|JSON_THROW_ON_ERROR);exit; }
